<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Bootstrap\App; use App\Database\Database; use App\Modules\Platform\PlatformAuditService; use App\Modules\Platform\PlatformRepository; use App\Support\Csrf; use App\Support\PlatformAuth; use App\Support\Session; use function App\Support\e;
new App(); $db=Database::connection(); $platformUser=PlatformAuth::requireAdmin($db); $repo=new PlatformRepository($db); $audit=new PlatformAuditService($db); $error=Session::consumeFlash('error'); $success=Session::consumeFlash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::verify($_POST['_csrf']??null)){ Session::flash('error','Your session expired. Please try again.'); header('Location: '.PlatformAuth::basePath().'/users'); exit; }
 $action=(string)($_POST['action']??'');
 if($action==='create'){
  if($platformUser['role']!=='super_admin'){ Session::flash('error','Only a super administrator can create platform users.'); header('Location: '.PlatformAuth::basePath().'/users'); exit; }
  $first=trim((string)($_POST['first_name']??'')); $last=trim((string)($_POST['last_name']??'')); $phone=trim((string)($_POST['phone']??'')); $email=trim((string)($_POST['email']??'')); $role=in_array($_POST['role']??'', ['admin','super_admin'],true)?(string)$_POST['role']:'admin'; $password=(string)($_POST['password']??'');
  if($first===''||$phone===''||!preg_match('/^.{8,}$/',$password)){ Session::flash('error','First name, phone and a password of at least 8 characters are required.'); header('Location: '.PlatformAuth::basePath().'/users'); exit; }
  try{$q=$db->prepare('INSERT INTO platform_users (first_name,last_name,phone,email,password_hash,role,status) VALUES (:first,:last,:phone,:email,:hash,:role,"active")');$q->execute(['first'=>$first,'last'=>$last?:null,'phone'=>$phone,'email'=>$email?:null,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);$id=(int)$db->lastInsertId();$audit->record((int)$platformUser['id'],'platform_user.created','Created platform user', 'platform_user',$id,['role'=>$role,'phone'=>$phone]);Session::flash('success','Platform user created.');}catch(\Throwable $e){Session::flash('error','Could not create the platform user. The phone or email may already exist.');}
  header('Location: '.PlatformAuth::basePath().'/users'); exit;
 }
 if($action==='toggle'){
  $id=(int)($_POST['id']??0); if($id===(int)$platformUser['id']){Session::flash('error','You cannot suspend your own account.');header('Location: '.PlatformAuth::basePath().'/users');exit;}
  if($platformUser['role']!=='super_admin'){Session::flash('error','Only a super administrator can change platform-user status.');header('Location: '.PlatformAuth::basePath().'/users');exit;}
  $q=$db->prepare('SELECT id,role,status FROM platform_users WHERE id=:id LIMIT 1');$q->execute(['id'=>$id]);$target=$q->fetch();
  if(!$target){Session::flash('error','Platform user not found.');} elseif($target['role']==='super_admin' && $target['status']==='active'){ $count=(int)$db->query("SELECT COUNT(*) FROM platform_users WHERE role='super_admin' AND status='active'")->fetchColumn(); if($count<=1){Session::flash('error','At least one active super administrator must remain.');} else {$new=$target['status']==='active'?'suspended':'active';$u=$db->prepare('UPDATE platform_users SET status=:status WHERE id=:id');$u->execute(['status'=>$new,'id'=>$id]);$audit->record((int)$platformUser['id'],'platform_user.status_changed','Changed platform user status','platform_user',$id,['status'=>$new]);Session::flash('success','Platform user status updated.');}} else {$new=$target['status']==='active'?'suspended':'active';$u=$db->prepare('UPDATE platform_users SET status=:status WHERE id=:id');$u->execute(['status'=>$new,'id'=>$id]);$audit->record((int)$platformUser['id'],'platform_user.status_changed','Changed platform user status','platform_user',$id,['status'=>$new]);Session::flash('success','Platform user status updated.');}
  header('Location: '.PlatformAuth::basePath().'/users');exit;
 }
}
$users=$repo->platformUsers(); ob_start(); ?>
<div class="row g-4"><div class="col-xl-4"><section class="platform-panel"><div class="platform-panel-head"><div><h2>Add platform user</h2><p>Only super administrators can create staff accounts.</p></div></div><div class="p-3"><form method="post"><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert alert-success"><?= e($success) ?></div><?php endif; ?><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="create"><div class="mb-2"><label class="form-label small fw-semibold">First name</label><input class="form-control" name="first_name" required></div><div class="mb-2"><label class="form-label small fw-semibold">Last name</label><input class="form-control" name="last_name"></div><div class="mb-2"><label class="form-label small fw-semibold">Phone</label><input class="form-control" name="phone" required></div><div class="mb-2"><label class="form-label small fw-semibold">Email</label><input class="form-control" type="email" name="email"></div><div class="mb-2"><label class="form-label small fw-semibold">Role</label><select class="form-select" name="role"><option value="admin">Admin</option><option value="super_admin">Super Admin</option></select></div><div class="mb-3"><label class="form-label small fw-semibold">Temporary password</label><input class="form-control" type="password" name="password" minlength="8" required></div><button class="btn btn-primary w-100" <?= $platformUser['role']!=='super_admin'?'disabled':'' ?>>Create platform user</button></form></div></section></div><div class="col-xl-8"><section class="platform-panel"><div class="platform-panel-head"><div><h2>Platform users</h2><p>These accounts are completely separate from merchant users.</p></div><span class="platform-muted"><?= number_format(count($users)) ?> users</span></div><div class="table-responsive"><table class="table platform-table align-middle mb-0"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><div class="fw-semibold"><?= e(trim($u['first_name'].' '.($u['last_name']??''))) ?></div><div class="platform-muted"><?= e($u['email']??$u['phone']) ?></div></td><td><?= e(ucwords(str_replace('_',' ',$u['role']))) ?></td><td><span class="status-badge <?= e($u['status']==='active'?'status-active':'status-expired') ?>"><?= e(ucfirst($u['status'])) ?></span></td><td class="platform-muted"><?= $u['last_login_at']?e(date('d M Y H:i',strtotime($u['last_login_at']))):'Never' ?></td><td class="text-end"><?php if((int)$u['id']!==(int)$platformUser['id'] && $platformUser['role']==='super_admin'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="btn btn-sm btn-light border"><?= $u['status']==='active'?'Suspend':'Activate' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div></div>
<?php $content=ob_get_clean();$title='Platform Users';$platformSection='users';require dirname(__DIR__,2).'/app/Views/layouts/platform.php';
